package com.miniforce.service;
import com.miniforce.exception.UnauthorizedException; import com.miniforce.model.User; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component;
@Component public class CurrentUser { public java.util.Optional<User> optional(){Authentication a=SecurityContextHolder.getContext().getAuthentication(); if(a==null||!(a.getPrincipal() instanceof User u)) return java.util.Optional.empty(); return java.util.Optional.of(u);} public User require(){Authentication a=SecurityContextHolder.getContext().getAuthentication(); if(a==null||!(a.getPrincipal() instanceof User u)) throw new UnauthorizedException("Authentication required"); return u;} }
